// approved work item and never for iHub's own field write-back.
const items = root && root.changelog && root.changelog.items;
if (!Array.isArray(items)) return 'false';
const approved = "{{{_flow.APPROVED_STATUS_NAME}}}".trim().toLowerCase();
return items.some((entry) => String(entry.field || entry.fieldId || '').toLowerCase() === 'status'
  && String(typeof entry.toString === 'string' ? entry.toString : '').trim().toLowerCase() === approved) ? 'true' : 'false';

const issue = (scope && scope.issue) || (scope && scope.payload && scope.payload.issue) || {};
const fields = issue.fields || {};
// Option -> value, user -> emailAddress, request type -> name, list -> first entry.
const flat = (v) => {
  if (v === null || v === undefined) return '';
  if (Array.isArray(v)) return v.length ? flat(v[0]) : '';
  if (typeof v === 'object') return flat(v.value !== undefined ? v.value : v.emailAddress !== undefined ? v.emailAddress : v.requestType ? v.requestType.name : v.name);
  return String(v).trim();
};
const field = (id) => (id ? flat(fields[id]) : '');
const json = (s) => String(s).replace(/\\/g, '\\\\').replace(/"/g, '\\"').replace(/\r?\n/g, '\\n').replace(/\t/g, '\\t');

// With REQUEST_TYPE_NAME empty every request of the configured work item type qualifies.
const wanted = "{{{_flow.REQUEST_TYPE_NAME}}}".trim().toLowerCase();
if (!wanted) return 'true';
return field('{{{_flow.JIRA_REQUEST_TYPE_FIELD}}}').toLowerCase() === wanted ? 'true' : 'false';

