const start = date(field('{{{_flow.JIRA_START_DATE_FIELD}}}'));
if (start && !/^\d{4}-\d{2}-\d{2}$/.test(start)) errors.push('Start date "' + start + '" is not a YYYY-MM-DD date');
const weekly = hours(field('{{{_flow.JIRA_WEEKLY_HOURS_FIELD}}}'));
